create table public.project_submissions (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete restrict, student_id uuid not null references public.profiles(id) on delete restrict, composition_id uuid references public.music_compositions(id) on delete set null, content jsonb, status text not null default 'draft', submitted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.music_compositions add constraint music_compositions_project_submission_fk foreign key (project_submission_id) references public.project_submissions(id) on delete set null;;
